styles.text:
.mp-lang-picker{position:relative;width:100%;min-width:0;direction:ltr}
.mp-lang-native{position:absolute!important;width:1px!important;height:1px!important;opacity:0!important;pointer-events:none!important;clip:rect(0 0 0 0)!important;clip-path:inset(50%)!important;overflow:hidden!important;white-space:nowrap!important}
.mp-lang-button{width:100%;min-height:40px;display:flex;align-items:center;gap:9px;border:1px solid var(--line,#d8e4ef);background:#fff;color:var(--text,#0b1b34);border-radius:12px;padding:8px 34px 8px 11px;font:inherit;font-weight:800;text-align:left;cursor:pointer;position:relative}
.mp-lang-button:hover{border-color:#9bc8d7}.mp-lang-button:focus-visible{outline:0;border-color:var(--primary2,#1b7aa2);box-shadow:0 0 0 3px rgba(27,122,162,.12)}
.mp-lang-button:after{content:'⌄';position:absolute;right:11px;top:50%;transform:translateY(-53%);font-size:15px;color:#344054}
.mp-lang-flag{display:inline-flex;flex:0 0 24px;width:24px;height:16px;border-radius:2px;overflow:hidden;box-shadow:0 0 0 1px rgba(16,24,40,.16);background:#fff}
.mp-lang-flag svg{display:block;width:24px;height:16px}
.mp-lang-name{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;direction:auto}
.mp-lang-menu{display:none;position:absolute;z-index:2147483640;top:calc(100% + 5px);left:0;width:100%;min-width:180px;max-height:330px;overflow:auto;padding:5px;background:#fff;border:1px solid #c9d9e7;border-radius:12px;box-shadow:0 14px 30px rgba(15,35,55,.18)}
.mp-lang-picker.open .mp-lang-menu{display:block}
.mp-lang-option{width:100%;display:flex;align-items:center;gap:9px;border:0;border-radius:8px;background:#fff;color:#0b1b34;padding:8px 9px;font:inherit;font-weight:650;text-align:left;cursor:pointer}
.mp-lang-option:hover,.mp-lang-option:focus-visible{outline:0;background:#eef6fb}.mp-lang-option[aria-current="true"]{background:#e7f3fb;font-weight:850}
#mpHomeScreen .mph-lang .mp-lang-picker{width:150px}#mpHomeScreen .mph-lang .mp-lang-button{min-height:36px;padding-top:7px;padding-bottom:7px;border-radius:11px}
@media(max-width:560px){#mpHomeScreen .mph-lang .mp-lang-picker{width:132px}}

.mp24-block{border:1px solid var(--line);border-radius:16px;background:#fff;padding:14px;margin:12px 0}
.mp24-grid{display:grid;gap:12px;margin-top:10px}.mp24-grid-2{grid-template-columns:repeat(2,minmax(0,1fr))}.mp24-grid-3{grid-template-columns:repeat(3,minmax(0,1fr))}.mp24-grid-results{grid-template-columns:repeat(2,minmax(0,1fr))}
.mp24-asset{border:1px solid var(--line);border-radius:14px;background:#fbfdff;padding:10px}.mp24-asset-title{font-weight:800;color:var(--primary);margin-bottom:8px}.mp24-asset img{width:100%;height:auto;border-radius:10px;display:block;border:1px solid #dfe8ef}.mp24-asset.inline img{max-height:240px;object-fit:contain;background:#fff}
.mp24-card h4,.mp24-block h4,.mp24-result-card h4{margin:0 0 8px;color:var(--primary)}
.mp24-result-card{border:1px solid var(--line);border-radius:16px;background:#fff;padding:12px;position:relative}.mp24-result-card.incomplete{border-color:#f6c36e;background:#fff8ed}
.mp24-ribbon{display:flex;gap:8px;justify-content:flex-end;margin-bottom:10px}.mp24-ribbon span{padding:4px 9px;border-radius:999px;font-size:.78rem;font-weight:900;border:1px solid var(--line)}.mp24-ribbon .ok{background:#ecfdf3;color:#067647;border-color:#abefc6}.mp24-ribbon .warn{background:#fff8ed;color:#b54708;border-color:#f6c36e}
.mp24-table{width:100%;border-collapse:collapse}.mp24-table th,.mp24-table td{padding:7px 8px;border-top:1px solid #e7edf3;vertical-align:top;text-align:left}.mp24-table th{width:34%;color:#35536b}.mp24-table.compact th{width:42%}
.mp24-note{margin-top:10px;padding:10px 12px;border-radius:12px;background:#f9fafb;border-left:4px solid #d0d5dd}.mp24-note.mild{background:#fff8ed;border-left-color:#f6c36e}.mp24-note.okbg{background:#ecfdf3;border-left-color:#12b76a}.mp24-note.warnbg{background:#fff8ed;border-left-color:#f79009}
.mp24-timeline{position:relative;padding-left:4px}.mp24-time-item{display:flex;gap:12px;position:relative;padding:0 0 12px 0}.mp24-time-item:last-child{padding-bottom:0}.mp24-time-body{padding:0 0 4px}.mp24-time-dot{width:14px;height:14px;border-radius:50%;margin-top:4px;flex:0 0 14px;background:#cbd5e1;border:2px solid #94a3b8}.mp24-time-item.done .mp24-time-dot{background:#1b7aa2;border-color:#1b7aa2}.mp24-time-item:not(:last-child)::after{content:'';position:absolute;left:6px;top:20px;width:2px;height:calc(100% - 8px);background:#d6e6ed}.mp24-time-item.done:not(:last-child)::after{background:#86c2d5}
@media(max-width:1100px){.mp24-grid-2,.mp24-grid-3,.mp24-grid-results{grid-template-columns:1fr}}

.mp24c-top-timeline{display:flex!important;grid-template-columns:none!important;align-items:flex-start;gap:0;overflow-x:auto;overflow-y:hidden;padding:12px 10px 10px!important;margin:0!important;background:linear-gradient(180deg,#fff,#f8fcff);scrollbar-width:thin;scroll-behavior:smooth}
.mp24c-top-step{--tl:#1b7aa2;position:relative;appearance:none;border:0;background:transparent;min-width:124px;flex:1 0 124px;padding:0 8px 8px;color:#425b70;font:inherit;text-align:center;cursor:default}
.mp24c-top-step:not(:last-child)::after{content:'';position:absolute;left:calc(50% + 22px);right:calc(-50% + 22px);top:18px;height:3px;border-radius:999px;background:#d9e4ec;z-index:0}
.mp24c-top-step.done:not(:last-child)::after{background:linear-gradient(90deg,var(--tl),#89bfd0)}
.mp24c-top-marker{position:relative;z-index:1;display:grid;place-items:center;width:38px;height:38px;margin:0 auto 7px;border-radius:50%;border:2px solid #b8c7d3;background:#fff;color:#667d90;font-weight:900;box-shadow:0 2px 7px rgba(15,76,117,.07)}
.mp24c-top-label{display:block;font-size:.77rem;font-weight:800;line-height:1.18;white-space:normal}
.mp24c-top-step.done .mp24c-top-marker{background:var(--tl);border-color:var(--tl);color:#fff}.mp24c-top-step.done .mp24c-top-label{color:#173e5a}
.mp24c-top-step.active .mp24c-top-marker{background:#fff;border:4px solid var(--tl);color:var(--tl);transform:scale(1.08);box-shadow:0 0 0 5px color-mix(in srgb,var(--tl) 12%,transparent)}
.mp24c-top-step.active .mp24c-top-label{color:#0b3554;font-weight:950}.mp24c-top-step.clickable{cursor:pointer}.mp24c-top-step.clickable:hover .mp24c-top-marker{transform:scale(1.09)}
.mp24c-top-step.locked{opacity:.50}.mp24c-top-step.locked .mp24c-top-marker{background:#f5f7f9}
.mp24c-top-step.blue{--tl:#217ea5}.mp24c-top-step.green{--tl:#4e9b5f}.mp24c-top-step.orange{--tl:#e58416}.mp24c-top-step.purple{--tl:#7b51c8}.mp24c-top-step.teal{--tl:#209b9b}.mp24c-top-step.pink{--tl:#cf3d84}
@media(max-width:1200px){.mp24c-top-step{min-width:110px;flex-basis:110px}.mp24c-top-label{font-size:.72rem}}
@media(max-width:760px){.mp24c-top-timeline{padding-left:4px!important;padding-right:4px!important}.mp24c-top-step{min-width:96px;flex-basis:96px;padding-left:4px;padding-right:4px}.mp24c-top-marker{width:34px;height:34px}.mp24c-top-step:not(:last-child)::after{top:16px;left:calc(50% + 20px);right:calc(-50% + 20px)}}

.lab24-section{border-color:#a9cbd9;background:linear-gradient(180deg,#fff 0%,#f8fcff 100%)}

.lab24-section-title{align-items:flex-start}.lab24-pill{display:inline-flex;align-items:center;border-radius:999px;padding:4px 9px;font-size:.7rem;font-weight:900;letter-spacing:.02em;border:1px solid #cfdae3;background:#fff;color:#35536b;margin:0 5px 4px 0}.lab24-pill.navy{background:#0f4c75;color:#fff;border-color:#0f4c75}.lab24-pill.soft{background:#eef7fb;color:#245a75;border-color:#c4dfea}.lab24-pill.ok{background:#ecfdf3;color:#067647;border-color:#abefc6}.lab24-pill.warn{background:#fff8ed;color:#b54708;border-color:#f6c36e}.lab24-pill.flag{background:#fff1f0;color:#b42318;border-color:#f6b5af}
.lab24-console{border:1px solid #9fc4d3;border-radius:18px;background:linear-gradient(135deg,#0d3d61,#145d82);color:#fff;padding:16px;margin:12px 0;box-shadow:0 12px 24px rgba(15,76,117,.12)}.lab24-console-head,.lab24-release-head,.lab24-block-head,.lab24-data-head{display:flex;gap:14px;align-items:center;justify-content:space-between}.lab24-console-head strong,.lab24-release-head strong{display:block;font-size:1.15rem;margin-top:2px}.lab24-eyebrow{display:block;text-transform:uppercase;font-size:.68rem;letter-spacing:.12em;font-weight:900;opacity:.72}.lab24-kpi-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-top:14px}.lab24-kpi-grid>div{background:rgba(255,255,255,.10);border:1px solid rgba(255,255,255,.18);border-radius:14px;padding:12px}.lab24-kpi-grid span{display:block;font-size:.72rem;opacity:.8}.lab24-kpi-grid b{display:block;font-size:1.15rem;margin:4px 0}.lab24-kpi-grid small{display:block;line-height:1.25;opacity:.78}.lab24-opening{margin-top:14px}
.lab24-block,.lab24-data-card,.lab24-plate-card{border:1px solid var(--line);border-radius:16px;background:#fff;padding:14px;margin:12px 0}.lab24-block-head h4,.lab24-data-head h4{margin:0;color:var(--primary)}
.lab24-qc-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin:12px 0}.lab24-qc{border:1px solid #d8e2ea;border-radius:14px;background:#fbfdff;padding:12px;position:relative;overflow:hidden}.lab24-qc:before{content:'';position:absolute;left:0;top:0;bottom:0;width:4px;background:#98a2b3}.lab24-qc.ok:before{background:#12b76a}.lab24-qc.flag:before{background:#d92d20}.lab24-qc span{display:block;font-size:.72rem;color:#667085}.lab24-qc b{display:block;font-size:1rem;margin:5px 0;color:#173e5a}.lab24-qc.flag b{color:#b42318}.lab24-qc small{color:#667085}
.lab24-table-wrap{overflow:auto}.lab24-table{width:100%;border-collapse:collapse;margin-top:10px}.lab24-table th,.lab24-table td{padding:9px 10px;border-top:1px solid #e6edf2;text-align:left;white-space:nowrap}.lab24-table thead th{font-size:.74rem;color:#667085;text-transform:uppercase;letter-spacing:.04em;background:#f8fafc}.lab24-table tr.ntc{background:#fff7f6}.lab24-vaf{font-weight:900;color:#b42318}
.lab24-media-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-top:10px}.lab24-media{margin:0;border:1px solid #d9e4ec;border-radius:14px;padding:9px;background:#fbfdff}.lab24-media figcaption{font-weight:900;color:#173e5a;margin:2px 2px 8px}.lab24-media img{display:block;width:100%;height:auto;border:1px solid #dde6ec;border-radius:10px;background:#fff}.lab24-synthetic{font-size:.65rem;color:#667085;margin:7px 2px 0}.lab24-media-lock{display:flex;gap:12px;align-items:center;border:1px dashed #cbd5e1;border-radius:16px;background:#f8fafc;padding:14px;margin:12px 0}.lab24-media-lock p{margin:4px 0 0;color:#667085}.lab24-lock-icon{font-size:1.25rem}
.lab24-reasoning-evidence{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin:12px 0}.lab24-reasoning-evidence>div{border:1px solid #d9e4ec;background:#fbfdff;border-radius:12px;padding:10px}.lab24-reasoning-evidence span{display:block;font-size:.7rem;color:#667085}.lab24-reasoning-evidence b{display:block;margin-top:3px;color:#173e5a}.lab24-reasoning .gate-question{border-radius:16px}.lab24-reasoning .gate-option{border-radius:12px}
.lab24-release-head{border:1px solid #b9d4df;border-radius:16px;background:linear-gradient(135deg,#eff9ff,#fff);padding:14px;margin:12px 0}.lab24-release-head.audit{background:linear-gradient(135deg,#f3faf7,#fff);border-color:#b7dfca}.lab24-choice-grid{display:grid;gap:10px}.lab24-decision{display:grid!important;grid-template-columns:42px 22px 1fr;align-items:flex-start;gap:10px}.lab24-choice-index{display:grid;place-items:center;width:34px;height:34px;border-radius:10px;background:#eef7fb;color:#245a75;font-weight:900}.lab24-decision.selected .lab24-choice-index{background:#0f4c75;color:#fff}
.lab24-investigation-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:10px}.lab24-investigation{display:flex;gap:10px;border:1px solid #d8e2ea;border-radius:14px;background:#fff;padding:12px;cursor:pointer}.lab24-investigation.selected{border-color:#78b7cd;background:#f2fbff;box-shadow:0 0 0 2px rgba(27,122,162,.08)}.lab24-investigation input{margin-top:4px}.lab24-investigation-num{display:inline-flex;min-width:28px;height:24px;align-items:center;justify-content:center;border-radius:8px;background:#eef2f6;color:#667085;font-size:.7rem;font-weight:900;margin-right:7px}.lab24-investigation p{margin:6px 0 0}
.lab24-plate-card{overflow:hidden}.lab24-plate-scroll{overflow:auto;padding-top:8px}.lab24-plate{min-width:560px;display:grid;grid-template-columns:28px repeat(12,minmax(38px,1fr));gap:3px}.lab24-collab,.lab24-rowlab{display:grid;place-items:center;font-weight:900;color:#527086;font-size:.78rem}.lab24-well{height:46px;border:1px solid #d7e1e8;border-radius:10px;background:#f8fafc;display:flex;flex-direction:column;align-items:center;justify-content:center;line-height:1.05}.lab24-well span{font-weight:900;font-size:.78rem}.lab24-well small{margin-top:3px;font-size:.66rem}.lab24-well.px{background:#f2f8ff;border-color:#b9d5ef;color:#175b91}.lab24-well.pc{background:#ecfdf3;border-color:#75d49d;color:#067647}.lab24-well.ntc{background:#fff1f0;border-color:#f0a6a0;color:#b42318}.lab24-well.low{background:#fff8df;border-color:#e4bd54;color:#9a6700}.lab24-well.empty{color:#c1cbd4}.lab24-legend{display:flex;gap:6px;flex-wrap:wrap}.lab24-legend span{padding:3px 7px;border-radius:7px;font-size:.68rem;font-weight:900}.lab24-legend .pc{background:#ecfdf3;color:#067647}.lab24-legend .ntc{background:#fff1f0;color:#b42318}.lab24-legend .low{background:#fff8df;color:#9a6700}.lab24-legend .px{background:#f2f8ff;color:#175b91}
.lab24-capa-flow{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-top:12px}.lab24-capa-card{border:1px solid #d8e2ea;border-radius:14px;background:#fff;padding:12px;cursor:pointer;min-height:132px}.lab24-capa-card.selected{border-color:#63b7a2;background:#f0fbf7;box-shadow:0 0 0 2px rgba(18,183,106,.08)}.lab24-capa-card>input{float:right}.lab24-capa-top{display:flex;gap:8px;align-items:center;margin-bottom:8px}.lab24-capa-top span{display:grid;place-items:center;width:28px;height:28px;border-radius:9px;background:#eef2f6;color:#667085;font-size:.7rem;font-weight:900}.lab24-capa-card.selected .lab24-capa-top span{background:#12b76a;color:#fff}.lab24-capa-card p{margin:0;color:#475467;font-size:.82rem;line-height:1.35}
