.lab24-top-timeline{display:flex!important;grid-template-columns:none!important;align-items:flex-start;gap:0;overflow-x:auto;overflow-y:hidden;padding:12px 10px 10px!important;margin:0!important;background:linear-gradient(180deg,#fff,#f8fcff);scrollbar-width:thin;scroll-behavior:smooth}.lab24-top-step{--tl:#1b7aa2;position:relative;appearance:none;border:0;background:transparent;min-width:122px;flex:1 0 122px;padding:0 7px 8px;color:#425b70;font:inherit;text-align:center;cursor:default}.lab24-top-step:not(:last-child)::after{content:'';position:absolute;left:calc(50% + 22px);right:calc(-50% + 22px);top:18px;height:3px;border-radius:999px;background:#d9e4ec;z-index:0}.lab24-top-step.done:not(:last-child)::after{background:linear-gradient(90deg,var(--tl),#9ec8d6)}.lab24-top-marker{position:relative;z-index:1;display:grid;place-items:center;width:38px;height:38px;margin:0 auto 7px;border-radius:50%;border:2px solid #b8c7d3;background:#fff;color:#667d90;font-weight:900;box-shadow:0 2px 7px rgba(15,76,117,.07)}.lab24-top-label{display:block;font-size:.76rem;font-weight:850;line-height:1.18}.lab24-top-step.done .lab24-top-marker{background:var(--tl);border-color:var(--tl);color:#fff}.lab24-top-step.active .lab24-top-marker{background:#fff;border:4px solid var(--tl);color:var(--tl);transform:scale(1.08);box-shadow:0 0 0 5px color-mix(in srgb,var(--tl) 12%,transparent)}.lab24-top-step.active .lab24-top-label{color:#0b3554;font-weight:950}.lab24-top-step.clickable{cursor:pointer}.lab24-top-step.clickable:hover .lab24-top-marker{transform:scale(1.09)}.lab24-top-step.locked{opacity:.45}.lab24-top-step.blue{--tl:#217ea5}.lab24-top-step.orange{--tl:#e58416}.lab24-top-step.purple{--tl:#7b51c8}.lab24-top-step.red{--tl:#d44a3a}.lab24-top-step.teal{--tl:#209b9b}.lab24-top-step.green{--tl:#4e9b5f}.lab24-top-step.navy{--tl:#0f4c75}
