#mpHomeScreen .mph-mini-brand{display:flex;align-items:center;gap:10px;font-size:.84rem;font-weight:850;color:#0f4c75;letter-spacing:.01em}.mph-mini-brand img{width:42px;height:42px;object-fit:contain;border-radius:50%;filter:drop-shadow(0 6px 12px rgba(15,76,117,.12))}
