#mpHomeScreen h1{all:unset;display:block;color:#0f4c75;font:900 clamp(2.45rem,7vw,5.2rem)/.93 Inter,ui-sans-serif,system-ui,sans-serif;letter-spacing:-.055em;margin:0 0 18px!important}#mpHomeScreen .mph-sub{margin:0 0 24px;color:#526276;font-size:clamp(1rem,2.1vw,1.22rem);line-height:1.55;max-width:700px}
#mpHomeScreen .mph-actions{display:flex;gap:10px;flex-wrap:wrap}#mpHomeScreen button{font:inherit}#mpHomeScreen .mph-btn{border:1px solid #cad9e5;border-radius:14px;padding:12px 17px;background:#fff;color:#0f4c75;font-weight:900;cursor:pointer;min-height:48px;box-shadow:0 7px 18px rgba(15,35,55,.06)}#mpHomeScreen .mph-btn.primary{border:0;color:#fff;background:linear-gradient(135deg,#0f4c75,#1b7aa2);box-shadow:0 12px 26px rgba(15,76,117,.22)}#mpHomeScreen .mph-btn:hover{transform:translateY(-1px)}#mpHomeScreen .mph-btn:active{transform:translateY(0)}
#mpHomeScreen .mph-logo-zone{display:grid;place-items:center;min-height:240px;position:relative}#mpHomeScreen .mph-logo-zone:before,#mpHomeScreen .mph-logo-zone:after{content:'';position:absolute;border-radius:50%;border:1px solid rgba(27,122,162,.12)}#mpHomeScreen .mph-logo-zone:before{width:92%;aspect-ratio:1/1}#mpHomeScreen .mph-logo-zone:after{width:72%;aspect-ratio:1/1;border-color:rgba(15,118,110,.13)}#mpHomeScreen .mph-logo{position:relative;z-index:1;width:min(72%,245px);height:auto;object-fit:contain;border-radius:50%;filter:drop-shadow(0 22px 38px rgba(15,76,117,.19))}
#mpHomeScreen .mph-stats{display:flex;gap:10px;flex-wrap:wrap;margin-top:22px}#mpHomeScreen .mph-stat{display:inline-flex;align-items:center;gap:7px;border:1px solid #d6e3ed;background:#f8fbfd;border-radius:999px;padding:7px 11px;color:#475467;font-size:.76rem;font-weight:850}#mpHomeScreen .mph-stat b{color:#0f4c75}
#mpHomeScreen .mph-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}#mpHomeScreen .mph-card{appearance:none;text-align:left;border:1px solid #d5e2ec;border-radius:20px;background:rgba(255,255,255,.88);padding:20px;min-height:164px;color:#0b1b34;cursor:pointer;box-shadow:0 10px 28px rgba(15,35,55,.055);transition:.16s ease}#mpHomeScreen .mph-card:hover{border-color:#97c5d9;transform:translateY(-2px);box-shadow:0 15px 34px rgba(15,35,55,.09)}#mpHomeScreen .mph-card-icon{display:grid;place-items:center;width:44px;height:44px;border-radius:13px;background:#eef7fb;color:#0f4c75;font-size:1.25rem;margin-bottom:14px}#mpHomeScreen .mph-card strong{display:block;color:#0f4c75;font-size:1rem;margin-bottom:6px}#mpHomeScreen .mph-card span{display:block;color:#667085;font-size:.84rem;line-height:1.45}
