#mpHomeScreen .mph-guide{display:grid;gap:10px}#mpHomeScreen .mph-guide-row{display:grid;grid-template-columns:42px minmax(0,1fr);gap:12px;align-items:start;border:1px solid #e0e9f0;border-radius:15px;padding:13px;background:#fbfdfe}#mpHomeScreen .mph-num{display:grid;place-items:center;width:36px;height:36px;border-radius:50%;background:#0f4c75;color:#fff;font-weight:900}#mpHomeScreen .mph-guide-row b{display:block;color:#0f4c75;margin-bottom:3px}#mpHomeScreen .mph-guide-row div div{color:#667085;font-size:.86rem;line-height:1.45}
#mpHomeScreen .mph-mode-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}#mpHomeScreen .mph-mode{border:1px solid #dce7ef;border-radius:17px;padding:17px;background:#fbfdff}#mpHomeScreen .mph-mode-tag{display:inline-flex;border-radius:999px;padding:5px 9px;background:#e8f3ff;color:#0f4c75;font-size:.75rem;font-weight:900;margin-bottom:10px}#mpHomeScreen .mph-mode:nth-child(2) .mph-mode-tag{background:#ecfdf3;color:#067647}#mpHomeScreen .mph-mode:nth-child(3) .mph-mode-tag{background:#fff4e6;color:#b54708}#mpHomeScreen .mph-mode b{display:block;margin-bottom:6px;color:#0b1b34}#mpHomeScreen .mph-mode p{margin:0;color:#667085;font-size:.84rem;line-height:1.5}
#mpHomeScreen .mph-news{display:grid;gap:9px}#mpHomeScreen .mph-news-item{display:flex;gap:10px;align-items:flex-start;padding:11px 12px;border:1px solid #e1e9f0;border-radius:13px;background:#fbfdfe;color:#475467;font-size:.88rem}#mpHomeScreen .mph-news-item:before{content:'✓';display:grid;place-items:center;flex:0 0 24px;height:24px;border-radius:50%;background:#ecfdf3;color:#087443;font-weight:900}
